// План specs/dashboard.md 2.1, 2.4 (кейсы DB-04, DB-07). Десктоп 1440, admin, компания «test». Только просмотр (@prod-safe).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import { greetingCard } from './dashboard-helpers';
import {
  TIPS, expectNoInvoicesDueInCard, hideTipButton, openDashboardFresh, removeTipKeys, tipLink, waitForTip,
} from './dashboard-tips-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Дашборд, десктоп: в карточке приветствия совет вместо «Invoices due» (#444b9ee7)', () => {
  test.afterEach(async ({ page }) => { await removeTipKeys(page); });

  test('Desktop dashboard EN: greeting card has no "Invoices due", shows one tip and "On your schedule"; Invoices due only in Invoices Summary #444b9ee7 @desktop @prod-safe', async ({ page }) => {
    await openDashboardFresh(page, 'en');
    await waitForTip(page, 'en');

    const card = greetingCard(page);
    await expectNoInvoicesDueInCard(page);
    await expect(card).toContainText('On your schedule');
    await expect(tipLink(page, 'en')).toHaveCount(1);
    await expect(tipLink(page, 'en')).toHaveText(TIPS.stripe.text);

    // «Invoices due» есть на странице только в виджете Invoices Summary.
    await expect(page.getByText('Invoices Summary').first()).toBeVisible();
    const mentions = page.getByText(/Invoices due/i);
    const n = await mentions.count();
    expect(n, '«Invoices due» должно быть в виджете Invoices Summary').toBeGreaterThan(0);
    for (let i = 0; i < n; i++) {
      await expect(
        mentions.nth(i).locator('xpath=ancestor::*[contains(., "Invoices Summary")][1]'),
        '«Invoices due» встречается только внутри виджета Invoices Summary',
      ).toHaveCount(1);
    }
  });

  test('Desktop dashboard HE: tip in Hebrew with "הסתר טיפ" button, no "Invoices due" in greeting card #444b9ee7 @desktop @prod-safe', async ({ page }) => {
    await openDashboardFresh(page, 'he');
    await waitForTip(page, 'he');

    await expectNoInvoicesDueInCard(page);
    await expect(hideTipButton(page, 'en')).toHaveCount(0);
    const link = tipLink(page, 'he');
    await expect(link).toHaveCount(1);
    await expect(link).toHaveText(/[א-ת]/); // буквы иврита
    await expect(link).not.toHaveText(TIPS.stripe.text);
    await expect(link).toHaveAttribute('href', TIPS.stripe.href);
  });
});
